import hashlib,json,os
b=json.load(open('/tmp/hashes/before.json'))['web_files']
ch=[];new=[];gone=[]
cur={}
for dp,_d,fs in os.walk('assets/web'):
    for f in fs:
        p=os.path.join(dp,f); cur[os.path.relpath(p,'assets/web')]=hashlib.sha256(open(p,'rb').read()).hexdigest()
for k,v in sorted(cur.items()):
    if k not in b: new.append(k)
    elif b[k]!=v: ch.append(k)
gone=[k for k in b if k not in cur]
print('changed',len(ch),ch[:10]); print('new',len(new),new[:10]); print('gone',len(gone),gone[:10])
"
